// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    ACCURAL_DEPOSIT c;
    function setUp() public { c = new ACCURAL_DEPOSIT(); }
    function testFuzz_property(uint256 newMin) public {

        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            uint256 observed = c.MinSum();
            assertTrue(observed == newMin);
        } else {
            assertTrue(ok);
        }

        uint256 finalVal = c.MinSum();
        assertTrue(!ok || finalVal == newMin);
    }
}
